import{_ as l,o,c as e,ai as a}from"./chunks/framework.DAbPic9L.js";const h=JSON.parse('{"title":"产品业务流程","description":"","frontmatter":{},"headers":[],"relativePath":"products/product-process.md","filePath":"products/product-process.md","lastUpdated":1783097192000}'),t={name:"products/product-process.md"};function i(s,p,c,d,r,n){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="产品业务流程" tabindex="-1">产品业务流程 <a class="header-anchor" href="#产品业务流程" aria-label="Permalink to &quot;产品业务流程&quot;">​</a></h1><h2 id="业务需求产生" tabindex="-1">业务需求产生 <a class="header-anchor" href="#业务需求产生" aria-label="Permalink to &quot;业务需求产生&quot;">​</a></h2><p>项目开发流程基础类型：瀑布流、敏捷开发、迭代开发、看板管理。但最稳健的还是瀑布流类型，因此主要讲瀑布流的开发流程。</p><div class="warning custom-block"><p class="custom-block-title">业务需求产生</p><ol><li><p>市场痛点发现</p><p>主线任务：用户活动中切身想要完成的事物（功能实用与精神消耗）。</p><p>用户需求：围绕在主线任务过程中所期待的反馈（诉求、期待、满足感）。</p><p>市场痛点：围绕在主线任务过程中所遭遇的难题（问题、障碍、关卡点）。</p></li></ol><p>特别提醒：市场痛点的发现，目的在于完成主线任务，因此需要围绕主线任务展开，避免陷入痛点与需求自洽循环的陷阱。产品服务的价值意义，在于帮助市场用户解决主线任务问题；因此，市场用户才会愿意付费使用。</p><ol start="2"><li><p>用户调研分析</p><p>用户群体细分：完成主线任务时，哪些人群会在市场痛点和需求的范围内。</p><p>竟品列表与功能分析：帮助用户完成主线任务时，有哪些同行竟品服务和主要功能内容。</p><p>市场问卷与用户访谈：面向重点用户群体，通过市场问卷调查、用户现场访谈等方式建立沟通联系，搜集重点用户群体普遍存在的痛点与需求，竟品服务的特色功能和满意程度，询问用户期待哪种有效方式提供服务，以及支持产品服务来完成主线主线的少量付费意愿程度。</p></li></ol><p>特别提醒：用户调研分析的目的，在于搜集重点用户人群的实际痛点需求，竟品服务功能与特色，以及用户对竟品服务的满意层度和问题反馈，支持产品服务的少量付费意愿程度。</p><ol start="3"><li><p>商业画布设计</p><p>用户细分：围绕用户主线任务的痛点与需求，发现重点用户人群，并纳入服务范围。</p><p>价值主张：围绕用户主线任务，满足市场客户需求，产品服务带来价值。</p><p>渠道通路：围绕用户主线任务，与用户建立联系并沟通需求，将产品服务推向市场用户。</p><p>客户关系：不同用户人群在完成主线任务时的需要程度（临时、刚需、必需）。</p><p>收入来源：产品服务在某阶段业务过程所带来的利润来源；重点记住该盈利模式。</p><p>核心资源：主要体现在生产资料（土地、资本、技术、人力、才能等），为可持续发展提供支持。</p><p>关键业务：实现可持续盈利的业务活动；需掌握重点关键业务，产品经理必备技能。</p><p>重要合作：实现可持续盈利的重要参与者；需掌握生产资料的提供者，产品服务的推广者、消费者。</p><p>成本结构：支持产品服务可持续发展的所有成本要素（人力、资本、土地、技术等）。</p></li></ol><p>特别提醒：商业模式是指利用有限核心资源，提供有效产品服务，满足市场重点用户人群需求，实现可持续盈利的商业目标为导向而设计。通俗来讲，市场中有特定人群在完成主线任务时遇到普遍存在的痛点与需求，通过设计制定有效产品服务帮助该类重点人群完成主线任务，并收取少量的服务费用，从而实现可持续盈利的商业目标。因此，商业画布设计，本质上是业务模式和盈利模式的设计。</p></div><h2 id="制定可行性方案" tabindex="-1">制定可行性方案 <a class="header-anchor" href="#制定可行性方案" aria-label="Permalink to &quot;制定可行性方案&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">制定可行性方案</p><ol><li><p>产品定义与设计</p><p>产品功能：归纳重点用户人群的痛点需求列表，筛选并确定产品服务的核心业务功能。</p><p>特色功能：简洁高效，服务方便；突出产品价值，提升用户满意度，并构建品牌形象。</p><p>用户喜好：根据用户喜好（惯用操作方式），制定产品服务的个性化功能。</p></li></ol><p>特别提醒：产品定义与设计，必须围绕用户完成主线任务的痛点需求，制定简洁高效的核心业务功能，帮助用户完成主线任务。</p><ol start="2"><li><p>MVP 可行性方案</p><p>基础核心功能：明确核心业务功能，形成业务流程闭环；绘制业务流程图可有效理解。</p><p>市场快速验证：面向重点用户群体，根据环境范围周期性投放验证，并访谈用户与数据分析。</p></li></ol><p>特别提醒：MVP 可行性方案，目的在于验证重点用户人群的痛点需求的普遍程度和产品服务的使用程度，来明确产品服务的可行性。</p><ol start="3"><li><p>产品可行性评估</p><p>技术可行性评估：通过搜集、分析竟品功能的技术实现，以及结合市场可用性技术方案和风险作出评估产品服务的可行性。</p><p>成本利润比评估：通过商业画布设计方案，计算产品服务的成本与利润比，并评估产品服务的可持续性和盈利性。</p></li></ol><p>特别提醒：产品可行性评估，目的在于明确能否通过技术实现，并保证产品服务的可持续盈利。</p><ol start="4"><li><p>制定项目计划</p><p>业务流程流水线：根据业务流程绘制 WBS/甘特图，方便团队成员快速理解业务流程，并有效检出疑虑和风险。</p><p>业务资源分配表：根据业务流程需要，合理分配资源利用率，节本预算。</p><p>业务开发时间表：根据业务流程的模块优先级，合理安排业务模块功能的开发，并跟进项目进度适当调整内容（减需、延期、迭代）。</p></li></ol><p>特别提醒：制定项目计划，目的在于为团队指导前进方向，明确团队各成员职责，清晰理解业务流程，以便减少无效的沟通成本，方便产品服务功能的开发。</p><ol start="5"><li><p>架构分层设计</p><p>架构分层设计：根据业务流程，划分架构层级和业务领域，明确各架构层级和业务领域的职责职能和通信协作；主要由系统架构师负责。</p><p>网站架构信息：通过组织、结构化、标签化展示网站信息，降低用户心智，提升用户体验；主要由交互设计师负责。</p></li></ol><p>特别提醒：架构分层设计，目的在于明确各架构层级、业务领域的职责职能和通信协作等内容，使项目在技术实现具有清晰组织结构，有利于程序高效开发、版本迭代管瘤、异常追踪定位、运维管理分析。网站架构信息的设计与构建，有利于帮助用户快速找到所需内容，提升整体使用体验。</p><ol start="5"><li><p>团队组建和管理</p><p>团队成员构成：根据有限资源预算和业务功能所需数量，合理制定团队成员。</p><p>团队成员职责：根据业务流程或功能，根据岗位划分团队成员职责。</p><p>团队开发流程：制定业务流程开发计划，根据功能优先级跟进任务进度。</p><p>团队沟通协作：沟通方式采用现场交流和邮件通知，并备份记录最终共识内容；协作采用版本控制，并遵循条款约定协议守则。</p><p>团队风险管理：团队成本预算、团队技术水平、团队成员离职、团队奖惩激励。</p></li></ol></div><h2 id="开发产品服务" tabindex="-1">开发产品服务 <a class="header-anchor" href="#开发产品服务" aria-label="Permalink to &quot;开发产品服务&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">开发产品服务</p><ol><li><p>约定开发规范与协议</p><p>约定开发规范：制定并遵循版本控制(<code>git</code>)规范、统一编码规范（命名、格式、追踪标记）。服务或模块间的接口通信方式等。</p><p>约定开发协议：根据项目计划、岗位职责、模块分配，实现难度制定透明奖惩机制，激发个人潜能并提高团队氛围；另约定产品上线所得利润阶段性的额外分成（利润总额比的分成：半年 5%，一年 10%，两年 15%）。</p></li><li><p>迭代持续集成流水线</p><p>版本控制管理：通过版本控制(<code>git</code>)工具实现代吗版本分支控制。</p><p>代码仓库管理：通过远程远程仓库(<code>github | gitlab</code>)托管产品项目源码。</p><p>迭代部署管理：通过持续集成(<code>CI/CD</code>)自动化迭代、测试、部署项目服务。</p></li><li><p>领域建模与库表设计</p><p>业务对象模型：视图展示对象(<code>VO</code>，前端界面场景)、传输数据对象(<code>DTO</code>，服务接口场景)，库表实体对象(<code>Entity</code>，数据库表场景)。</p><p>库表设计原则：一对一，一张表，外键唯一；多字段可拆表。一对多，两张表，多的表存外键。多对多，三张表，第三张表存两个外键。索引字段目的在于提升查询效率，但因考虑性能（写操作-IUD 变慢），需慎用。索引设置技巧，等值优先、最左适配；常用于唯一索引（具体查询）、普通索引（条件查询）、组合索引（多字段最左适配等值查询，如多字段查询、分组排序查询），高阶用法看覆盖索引。索引不适用重复值字段、频繁更新值等场景。</p></li><li><p>业务编码与代吗评审</p><p>业务编码：根据业务流程模块内容，定义业务对象模型（高内聚、可测试、可维护），编写业务代码逻辑，实现核心业务功能。</p><p>交互设计师：构建网站架构信息，绘制交互原型图（线框稿），并与产品经理沟通交流，确保交互设计符合产品需求。</p><p>视觉设计师：设计视觉风格，还原视觉效果(<code>&gt;= 95%</code>)，并与产品经理沟通交流，确保视觉设计符合产品需求。</p><p>前端工程师：定义视图展示对象(<code>VO</code>)，编写前端页面组件，状态管理，浏览器兼容，性能优化等内容。</p><p>后端工程师：定义传输数据对象(<code>DTO</code>)，库表实体对象(<code>Entity</code>)，服务间的通信方式，编写服务接口，实现核心业务功能。</p><p>测试工程师：编写测试用例，并与开发人员沟通交流，确保测试用例符合产品需求。</p><p>代吗评审：统一编码规范，符合架构原则，提高代码质量，快速理解代码逻辑，有效识别安全漏洞。</p></li></ol><p>特别提醒：前端传递接口参数为视图展示对象(<code>VO</code>)，会经历序列化与反序列化过程，在这过程中不会序列化函数、<code>Symbol</code>属性、不可枚举属性、原型链属性等。</p><ol start="5"><li><p>开发文档与接口联调</p><p>开发文档：编写产品开发文档，包括功能说明、使用说明、接口文档、数据库设计、测试用例等；推荐使用<code>Swagger</code>自动生成工具。</p><p>接口联调：前后端必须约定接口协议、方式、参数等规范；可通过<code>Swagger</code>自动生成网页文档在线测试，或者 IDE 编就器安装插件(<code>REST Client</code>)进行联调。接口联调的本质是单次用例测试。</p></li><li><p>自动化测试</p><p><span class="text-red text-size-20">后续待补充</span></p></li><li><p>性能与安全</p><p><span class="text-red text-size-20">后续待补充</span></p></li><li><p>客户验收产品</p><p><span class="text-red text-size-20">后续待补充</span></p></li></ol></div><h2 id="项目部署上线" tabindex="-1">项目部署上线 <a class="header-anchor" href="#项目部署上线" aria-label="Permalink to &quot;项目部署上线&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">项目部署上线</p><p><span class="text-red text-size-20">后续待补充</span></p></div><h2 id="项目持续维护" tabindex="-1">项目持续维护 <a class="header-anchor" href="#项目持续维护" aria-label="Permalink to &quot;项目持续维护&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">项目持续维护</p><p><span class="text-red text-size-20">后续待补充</span></p></div><h2 id="案例场景分析" tabindex="-1">案例场景分析 <a class="header-anchor" href="#案例场景分析" aria-label="Permalink to &quot;案例场景分析&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">案例场景</p><p>主线任务：菜农卖菜；用户买菜。</p><p>用户需求：菜农希望大卖（早点卖完、多赚一点）；用户希望省钱省时买好菜（不出门可买，节省时间，省钱能买好菜）。</p><p>人群划分：卖方：菜农；买方：家庭主妇、家庭主男、保姆、临时买菜者。</p><p>市场痛点：菜农如何让目标人群知道，又如何赚多一点钱；用户如何省钱购买好品质菜品，甚至可以不出门可买菜。</p><p>竟品列表与用户分析：找到帮助菜农卖菜的同行产品、询问菜农的期望和满意度；用户通过各种渠道了解菜品质量、价格，省钱选择购买。</p><p>产品服务的平台功能：帮助菜农广而告之推销菜品，提供精美包装服务、品牌安全质检、送货上门等服务功能；帮助用户线上交易买菜，提供会员权益、积分等促销方式，提供外送服务解决用户的出行问题。</p><p>产品服务的核心业务：</p><ol><li>菜品信息：菜品名称、描述、图片、价格、销量、评价等。</li><li>菜品分类：菜品的分类、标签、热度、推荐等。</li><li>菜品评价：菜品的评价、点评、图片、时间、用户等。</li><li>菜品配送：菜品的配送、送货上门、送货时间、送达范围等。</li><li>菜品销售：菜品的销售、订单管理、支付方式、发票等。</li><li>菜品推荐：推荐菜品、菜品分类、菜品配送、菜品销售等。</li><li>菜品搜索：搜索菜品、菜品分类、菜品配送、菜品销售等。</li><li>菜品分析：菜品的销售趋势、品牌热度、品类热度、菜品热度等。</li></ol></div>',14)])])}const b=l(t,[["render",i]]);export{h as __pageData,b as default};
